/**
 * 同键重放：指纹一致返回首次结果（成功清单或拒绝原因），指纹不一致 409 且账户不变。
 */
private SurrenderResponse replay(RequestRow existing, String enterpriseCode) {
    String incomingFingerprint = Fingerprints.of(existing.requestId(), enterpriseCode,
            existing.complianceYear(), existing.allowanceAmount(), existing.offsetAmount());
    // 重放请求来自当前企业；requestId 已唯一绑定首次申请的企业/年度/明细，
    // 指纹覆盖全部字段，任一不一致（含换企业）均在此暴露。
    if (!incomingFingerprint.equals(existing.fingerprint())) {
        throw new IdempotencyConflictException(
                "requestId=" + existing.requestId() + " 已存在但申请参数不一致，拒绝处理且账户不变");
    }
    CertificateRow certificate = STATUS_RETIRED.equals(existing.status())
            ? requests.findCertificateByRequestId(existing.requestId()) : null;
    return buildResponse(existing.requestId(), enterpriseCode, existing.complianceYear(),
            existing.status(), existing.rejectReason(),
            existing.allowanceAmount(), existing.offsetAmount(),
            certificate == null ? null : certificate.certificateNo(),
            existing.processedUtc(), existing.id());
}

